{
  "Comment": "Data Analysis V2 Workflow - ERD and Data Lineage Generation",
  "StartAt": "CaptureStartTime",
  "States": {
    "CaptureStartTime": {
      "Type": "Pass",
      "Comment": "Capture workflow start time",
      "Parameters": {
        "started_at.$": "$$.State.EnteredTime"
      },
      "ResultPath": "$.workflow_metadata",
      "Next": "UpdateStatusRunning"
    },
    "UpdateStatusRunning": {
      "Type": "Task",
      "Comment": "Update job status to running",
      "Resource": "arn:aws:states:::aws-sdk:s3:putObject",
      "Parameters": {
        "Bucket": "code-transformation-v2",
        "Key.$": "States.Format('{}/{}/data_analysis_v2/jobs/{}/status.json', $.scout_account_id, $.application_name, $.job_id)",
        "Body": {
          "state": "running",
          "started_at.$": "$.workflow_metadata.started_at",
          "phase": "data_analysis",
          "message": "Analyzing data structures..."
        },
        "ContentType": "application/json"
      },
      "ResultPath": "$.status_update_result",
      "Next": "ParallelDataAnalysis"
    },
    "ParallelDataAnalysis": {
      "Type": "Parallel",
      "Comment": "Run Regex, AST, and AI data analyzers in parallel",
      "Branches": [
        {
          "StartAt": "RegexDataExtractor",
          "States": {
            "RegexDataExtractor": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "DataAnalysisV2RegexDataExtractor",
                "Payload": {
                  "job_id.$": "$.job_id",
                  "scout_account_id.$": "$.scout_account_id",
                  "application_name.$": "$.application_name",
                  "source_hash.$": "$.source_hash"
                }
              },
              "Retry": [
                {
                  "ErrorEquals": ["States.ALL"],
                  "IntervalSeconds": 2,
                  "MaxAttempts": 3,
                  "BackoffRate": 2.0
                }
              ],
              "End": true
            }
          }
        },
        {
          "StartAt": "ASTDataAnalyzer",
          "States": {
            "ASTDataAnalyzer": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "DataAnalysisV2ASTDataAnalyzer",
                "Payload": {
                  "job_id.$": "$.job_id",
                  "scout_account_id.$": "$.scout_account_id",
                  "application_name.$": "$.application_name",
                  "source_hash.$": "$.source_hash"
                }
              },
              "Retry": [
                {
                  "ErrorEquals": ["States.ALL"],
                  "IntervalSeconds": 2,
                  "MaxAttempts": 3,
                  "BackoffRate": 2.0
                }
              ],
              "End": true
            }
          }
        },
        {
          "StartAt": "PrepareDataBatches",
          "States": {
            "PrepareDataBatches": {
              "Type": "Task",
              "Comment": "Split files into batches for AI data analysis",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "DataAnalysisV2PrepareDataBatches",
                "Payload": {
                  "job_id.$": "$.job_id",
                  "scout_account_id.$": "$.scout_account_id",
                  "application_name.$": "$.application_name",
                  "source_hash.$": "$.source_hash"
                }
              },
              "ResultPath": "$.batch_preparation",
              "Next": "CheckBatchCount"
            },
            "CheckBatchCount": {
              "Type": "Choice",
              "Comment": "Check if there are batches to process",
              "Choices": [
                {
                  "Variable": "$.batch_preparation.Payload.body.total_batches",
                  "NumericGreaterThan": 0,
                  "Next": "DataAnalyzerMap"
                }
              ],
              "Default": "SkipAIDataAnalysis"
            },
            "DataAnalyzerMap": {
              "Type": "Map",
              "Comment": "Process AI data analysis batches in parallel",
              "MaxConcurrency": 40,
              "ItemsPath": "$.batch_preparation.Payload.body.batches",
              "Parameters": {
                "job_id.$": "$.job_id",
                "scout_account_id.$": "$.scout_account_id",
                "application_name.$": "$.application_name",
                "source_hash.$": "$.source_hash",
                "batch.$": "$$.Map.Item.Value"
              },
              "Iterator": {
                "StartAt": "ProcessDataBatch",
                "States": {
                  "ProcessDataBatch": {
                    "Type": "Task",
                    "Resource": "arn:aws:states:::lambda:invoke",
                    "Parameters": {
                      "FunctionName": "DataAnalysisV2BedrockAnalyzerBatch",
                      "Payload.$": "$"
                    },
                    "Retry": [
                      {
                        "ErrorEquals": ["States.ALL"],
                        "IntervalSeconds": 5,
                        "MaxAttempts": 3,
                        "BackoffRate": 2.0
                      }
                    ],
                    "End": true
                  }
                }
              },
              "ResultPath": "$.batch_results",
              "Next": "MergeDataBatches"
            },
            "MergeDataBatches": {
              "Type": "Task",
              "Comment": "Merge all AI data batch results",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "DataAnalysisV2MergeDataBatches",
                "Payload": {
                  "job_id.$": "$.job_id",
                  "scout_account_id.$": "$.scout_account_id",
                  "application_name.$": "$.application_name",
                  "source_hash.$": "$.source_hash",
                  "total_batches.$": "$.batch_preparation.Payload.body.total_batches",
                  "total_files.$": "$.batch_preparation.Payload.body.total_files"
                }
              },
              "End": true
            },
            "SkipAIDataAnalysis": {
              "Type": "Pass",
              "Comment": "No files to analyze with AI",
              "Result": {
                "statusCode": 200,
                "body": {
                  "status": "skipped",
                  "message": "No COBOL files for AI data analysis"
                }
              },
              "End": true
            }
          }
        }
      ],
      "ResultPath": "$.parallel_results",
      "Next": "UpdateStatusERDGeneration",
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "HandleDataAnalysisError",
          "ResultPath": "$.error"
        }
      ]
    },
    "UpdateStatusERDGeneration": {
      "Type": "Task",
      "Comment": "Update status to ERD generation phase",
      "Resource": "arn:aws:states:::aws-sdk:s3:putObject",
      "Parameters": {
        "Bucket": "code-transformation-v2",
        "Key.$": "States.Format('{}/{}/data_analysis_v2/jobs/{}/status.json', $.scout_account_id, $.application_name, $.job_id)",
        "Body": {
          "state": "running",
          "started_at.$": "$.workflow_metadata.started_at",
          "phase": "erd_generation",
          "message": "Generating ERD and data lineage..."
        },
        "ContentType": "application/json"
      },
      "ResultPath": "$.status_update_result",
      "Next": "ERDGenerator"
    },
    "ERDGenerator": {
      "Type": "Task",
      "Comment": "Generate ERD from all data analysis sources",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "DataAnalysisV2ERDGenerator",
        "Payload": {
          "job_id.$": "$.job_id",
          "scout_account_id.$": "$.scout_account_id",
          "application_name.$": "$.application_name",
          "source_hash.$": "$.source_hash"
        }
      },
      "ResultPath": "$.erd_result",
      "Next": "UpdateStatusCompleted",
      "Retry": [
        {
          "ErrorEquals": ["States.ALL"],
          "IntervalSeconds": 2,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "HandleERDGenerationError",
          "ResultPath": "$.error"
        }
      ]
    },
    "UpdateStatusCompleted": {
      "Type": "Task",
      "Comment": "Update job status to completed",
      "Resource": "arn:aws:states:::aws-sdk:s3:putObject",
      "Parameters": {
        "Bucket": "code-transformation-v2",
        "Key.$": "States.Format('{}/{}/data_analysis_v2/jobs/{}/status.json', $.scout_account_id, $.application_name, $.job_id)",
        "Body": {
          "state": "completed",
          "started_at.$": "$.workflow_metadata.started_at",
          "completed_at.$": "$$.State.EnteredTime",
          "phase": "completed",
          "message": "ERD generation completed successfully",
          "outputs": {
            "erd.$": "$.erd_result.Payload.body.output_path"
          }
        },
        "ContentType": "application/json"
      },
      "Next": "Success"
    },
    "Success": {
      "Type": "Succeed",
      "Comment": "Workflow completed successfully"
    },
    "HandleDataAnalysisError": {
      "Type": "Task",
      "Comment": "Handle data analysis failure",
      "Resource": "arn:aws:states:::aws-sdk:s3:putObject",
      "Parameters": {
        "Bucket": "code-transformation-v2",
        "Key.$": "States.Format('{}/{}/data_analysis_v2/jobs/{}/status.json', $.scout_account_id, $.application_name, $.job_id)",
        "Body": {
          "state": "failed",
          "started_at.$": "$.workflow_metadata.started_at",
          "failed_at.$": "$$.State.EnteredTime",
          "phase": "data_analysis",
          "error_type": "data_analysis_error",
          "error.$": "$.error"
        },
        "ContentType": "application/json"
      },
      "Next": "Failure"
    },
    "HandleERDGenerationError": {
      "Type": "Task",
      "Comment": "Handle ERD generation failure",
      "Resource": "arn:aws:states:::aws-sdk:s3:putObject",
      "Parameters": {
        "Bucket": "code-transformation-v2",
        "Key.$": "States.Format('{}/{}/data_analysis_v2/jobs/{}/status.json', $.scout_account_id, $.application_name, $.job_id)",
        "Body": {
          "state": "failed",
          "started_at.$": "$.workflow_metadata.started_at",
          "failed_at.$": "$$.State.EnteredTime",
          "phase": "erd_generation",
          "error_type": "erd_error",
          "error.$": "$.error"
        },
        "ContentType": "application/json"
      },
      "Next": "Failure"
    },
    "Failure": {
      "Type": "Fail",
      "Comment": "Workflow failed"
    }
  }
}
